      attribute :reference_id

      # @!attribute [r] valid
      #   @return [Boolean] Whether the account is valid (true only for an active/valid account status).
      attribute :valid

      # @!attribute [r] name_at_bank
      #   @return [String, nil] Account holder's name as registered with the bank.
      attribute :name_at_bank

      # @!attribute [r] bank_name
      #   @return [String, nil] Bank name.
      attribute :bank_name

      # @!attribute [r] utr
      #   @return [String, nil] UTR of the penny-drop transaction, when one was generated.
      attribute :utr

      # @!attribute [r] city
      #   @return [String, nil] City of the account-holding branch.
      attribute :city

      # @!attribute [r] branch
      #   @return [String, nil] Name of the account-holding branch.
      attribute :branch

      # @!attribute [r] micr
      #   @return [String, nil] MICR code of the branch.
      attribute :micr

      # @!attribute [r] name_match_score
      #   @return [String, nil] Name similarity score (0-100, as a string). Only present when a name was supplied.
      attribute :name_match_score

      # @!attribute [r] name_match_result
      #   @return [String, nil] Result of cross-checking the supplied name against nameAtBank. Only present when a name was supplied.
      attribute :name_match_result

      # @!attribute [r] account_status
      #   @return [String, nil] Raw account status from the bank/NPCI.
      attribute :account_status

      # @!attribute [r] account_status_code
      #   @return [String, nil] Machine-readable code for accountStatus.
