      #   @return [EstampWalletPart] The Service Fee Wallet.
      attribute :service_fee, model: EstampWalletPart

      # @!attribute [r] mode
      #   @return [String] live for a production key, test for a sandbox key.
      attribute :mode

      # @!attribute [r] simulated
